import java.util.concurrent.*;

public class BoundedThreadPool {
    private final ExecutorService executor;
    private final BlockingQueue<Runnable> taskQueue;

    public BoundedThreadPool(int corePoolSize, int maximumPoolSize, long keepAliveTime, TimeUnit unit, int capacity) {
        this.taskQueue = new ArrayBlockingQueue<>(capacity);
        this.executor = new ThreadPoolExecutor(
            corePoolSize,
            maximumPoolSize,
            keepAliveTime,
            unit,
            taskQueue
        );
    }

    public void execute(Runnable command) throws RejectedExecutionException {
        if (taskQueue.size() >= taskQueue.capacity()) {
            throw new RejectedExecutionException("Task queue is full");
        }
        executor.execute(command);
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}
